package com.example.price;

import io.github.resilience4j.circuitbreaker.annotation.CircuitBreaker;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;

@Component
public class PriceClient {
    private final RestClient restClient;

    public PriceClient(RestClient.Builder builder) {
        this.restClient = builder.baseUrl("https://prices.example.com").build();
    }

    @CircuitBreaker(name = "priceApi", fallbackMethod = "fallback")
    public Price fetch(long productId) {
        return restClient.get()
                .uri("/v1/prices/{id}", productId)
                .retrieve()
                .body(Price.class);
    }

    private Price fallback(Long productId, Exception e) {
        return Price.unknown(productId);
    }
}

